arguments.content:
/* ---- Reset & base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
    --clr-bg: #0f1117;
    --clr-surface: #1a1d28;
    --clr-surface-hover: #232736;
    --clr-accent: #6ee7b7;
    --clr-accent-dim: #34d399;
    --clr-soldout: #f472b6;
    --clr-text: #e2e8f0;
    --clr-text-muted: #94a3b8;
    --clr-border: #2d3348;
    --radius: 14px;
    --shadow: 0 4px 24px rgba(0,0,0,.35);
    --font: "Segoe UI", system-ui, -apple-system, sans-serif;
}

html { font-size: 16px; }

body {
    font-family: var(--font);
    background: var(--clr-bg);
    color: var(--clr-text);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    overflow-x: hidden;
}

/* ---- Header ---- */
header {
    text-align: center;
    padding: 2.5rem 1rem 1.5rem;
}

header h1 {
    font-size: clamp(1.35rem, 4vw, 2rem);
    font-weight: 700;
    letter-spacing: .02em;
    background: linear-gradient(135deg, var(--clr-accent), var(--clr-soldout));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

/* ---- Cards grid ---- */
.cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 1.25rem;
    max-width: 960px;
    width: 100%;
    padding: 0 1rem 1rem;
    margin: 0 auto;
}

/* ---- Card ---- */
.card {
    position: relative;
    background: var(--clr-surface);
    border: 1px solid var(--clr-border);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    overflow: hidden;
    transition: transform .2s ease, box-shadow .2s ease;
}

.card:hover,
.card:focus-visible {
    transform: translateY(-4px);
    box-shadow: 0 8px 32px rgba(110,231,183,.12);
}

.card__badge {
    position: absolute;
    top: .75rem;
    right: .75rem;
    font-size: .7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .08em;
    padding: .25rem .6rem;
    border-radius: 6px;
    background: var(--clr-accent-dim);
    color: #0f1117;
}

.card__badge--soldout {
    background: var(--clr-soldout);
    color: #0f1117;
}

.card__content {
    padding: 1.25rem 1.25rem 1.5rem;
}

.card__title {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: .5rem;
}

.card__desc {
    font-size: .92rem;
    color: var(--clr-text-muted);
    line-height: 1.55;
    margin-bottom: 1rem;
}

/* ---- Meta table ---- */
.card__meta {
    display: flex;
    flex-direction: column;
    gap: .4rem;
    margin-bottom: 1.15rem;
}

.card__meta-row {
    display: flex;
    gap: .45rem;
    font-size: .85rem;
}

.card__meta-row dt {
    color: var(--clr-accent-dim);
    font-weight: 600;
    min-width: 3rem;
}

.card__meta-row dd {
    color: var(--clr-text-muted);
}

/* ---- Action button ---- */
.card__action {
    display: inline-block;
    padding: .55rem 1.4rem;
    font-size: .88rem;
    font-weight: 600;
    color: #0f1117;
    background: var(--clr-accent);
    border: none;
    border-radius: 8px;
    text-decoration: none;
    cursor: pointer;
    transition: background .15s ease;
}

.card__action:hover { background: var(--clr-accent-dim); }
.card__action:focus-visible { outline: 2px solid var(--clr-accent); outline-offset: 2px; }

.card__action--soldout {
    background: var(--clr-soldout);
    cursor: default;
    opacity: .75;
}

/* ---- Reveal button ---- */
.reveal-btn {
    display: block;
    margin: .5rem auto 2.5rem;
    padding: .65rem 1.6rem;
    font-size: .9rem;
    font-weight: 600;
    color: var(--clr-accent);
    background: transparent;
    border: 2px solid var(--clr-accent);
    border-radius: 8px;
    cursor: pointer;
    transition: background .15s ease, color .15s ease;
}

.reveal-btn:hover {
    background: var(--clr-accent);
    color: #0f1117;
}

.reveal-btn:focus-visible {
    outline: 2px solid var(--clr-accent);
    outline-offset: 2px;
}

/* ---- Mobile ---- */
@media (max-width: 480px) {
    .cards {
        grid-template-columns: 1fr;
        padding: 0 .75rem 1rem;
    }

    header { padding: 2rem .75rem 1.25rem; }

    .card__content { padding: 1rem; }

    /* Prevent horizontal overflow at 375 px */
    body { max-width: 100vw; overflow-x: hidden; }
    .card { width: 100%; }
}

(function () {
    var btn = document.getElementById("revealBtn");
    var card = document.getElementById("midnight-card");

    if (!btn || !card) return;

    btn.addEventListener("click", function () {
        var shown = card.hasAttribute("hidden");
        if (shown) {
            card.removeAttribute("hidden");
            btn.setAttribute("aria-expanded", "true");
        } else {
            card.setAttribute("hidden", "");
            btn.setAttribute("aria-expanded", "false");
        }
    });
})();
